/**
 * Motion41 — "CANADA · DIGITAL INFRASTRUCTURE GRID"
 * 1920x1080 · 60 fps · 1440 frames (24 s) · PERFECT LOOP
 *
 * Peta TIDAK langsung jadi: terbentuk memancar dari Ottawa, lalu kamera
 * bergerak menerus (yaw + pitch + dolly, satu siklus penuh per loop → seam
 * nol). Teks sengaja minim supaya pembeli bisa menimpa teksnya sendiri.
 *
 * Geometri: Natural Earth (DOMAIN PUBLIK) via nvkelso/natural-earth-vector.
 *   - garis negara  : ne_10m_admin_0_countries
 *   - batas provinsi: ne_10m_admin_1_states_provinces (13 provinsi/teritori)
 *   - kota          : ne_10m_populated_places_simple
 *
 * PROYEKSI: Lambert Conformal Conic dengan parameter RESMI EPSG:3347
 * "NAD83 / Statistics Canada Lambert" — paralel standar 49 dan 77 LU,
 * meridian tengah 91,8667 BB, lintang asal 63,3907 LU. Inilah proyeksi yang
 * dipakai Statistics Canada dan NRCan untuk peta nasional, jadi bentuk kipas
 * khas Kanada persis seperti peta resminya. Diuji: 1 derajat lintang terukur
 * 111,0 km di 49 LU dan 111,5 km di 77 LU (benar 111,2 dan 111,6) — konformal
 * memang menjaga skala nyaris sempurna di antara kedua paralel standarnya,
 * yang penting untuk negara yang membentang 41 sampai 83 LU.
 *
 * 412 POLIGON DISARING JADI 29. Kanada adalah negara dengan poligon terbanyak
 * di seri ini: 412 cincin dan 68.193 titik mentah, hampir semuanya pulau
 * Arktik. Saringannya bukan sekadar "buang yang kecil" — ambangnya diturunkan
 * sampai 0,0005 luas daratan utama secara SENGAJA supaya Pulau Prince Edward
 * ikut lolos. PEI itu salah satu dari 13 provinsi: kalau garis pantainya
 * tersaring sementara batas provinsinya tetap digambar, hasilnya provinsi
 * melayang tanpa pantai. Kepulauan Arktik TIDAK disisipkan seperti Shetland
 * atau Canarias — kepulauan itu bagian utuh dari bentuk Kanada, bukan tempelan
 * terpencil.
 *
 * FRAMING: sudut kiri atas bbox adalah Laut Beaufort — laut kosong — jadi
 * blok judul aman meski petanya besar. Diuji 72 pose kamera pada MAPK 1,12:
 * peta 356..1507 px horizontal dan 77..1001 px vertikal, seimbang di keempat
 * sisi dan seluruhnya di dalam action-safe.
 *
 * Batas iterasi grid titik DIHITUNG dari bbox, bukan angka tetap.
 */
import React, {
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  random,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';
import {noise3D} from '@remotion/noise';

/* ═══════════════════════════════════════════════════════════ FONT */

const FONT_CSS = `
@font-face{font-family:'MxMono41';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-style:normal;font-display:block;}
@font-face{font-family:'MxTitle41';src:url(data:font/woff2;base64,) format('woff2');font-weight:700;font-style:normal;font-display:block;}
`;

let fontsPromise: Promise<unknown> | null = null;
const ensureFonts = () => {
  if (fontsPromise) return fontsPromise;
  const st = document.createElement('style');
  st.textContent = FONT_CSS;
  document.head.appendChild(st);
  fontsPromise = Promise.all([
    (document as any).fonts.load("400 24px 'MxMono41'"),
    (document as any).fonts.load("700 24px 'MxTitle41'"),
  ]).catch(() => null);
  return fontsPromise;
};

const useEmbeddedFonts = () => {
  const [handle] = useState(() => delayRender('fonts-motion41'));
  const [ready, setReady] = useState(false);
  useEffect(() => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      setReady(true);
      continueRender(handle);
    };
    const to = setTimeout(finish, 2500);
    ensureFonts().then(finish, finish);
    return () => clearTimeout(to);
  }, [handle]);
  return ready;
};

