const CITIES = RAW_CITIES.split(';').map((s) => {
  const [n, x, y, p] = s.split('|');
  return {n, x: Number(x), y: Number(y), pop: Number(p)};
});

const MB = (() => {
  let x1 = 1e9,
    y1 = 1e9,
    x2 = -1e9,
    y2 = -1e9;
  for (const r of COUNTRY)
    for (const [x, y] of r) {
      if (x < x1) x1 = x;
      if (x > x2) x2 = x;
      if (y < y1) y1 = y;
      if (y > y2) y2 = y;
    }
  return {x1, y1, x2, y2, cx: (x1 + x2) / 2, cy: (y1 + y2) / 2};
})();

const mw = (x: number, y: number): [number, number] => [
  (x - MB.cx) * MAPK,
  (y - MB.cy) * MAPK,
];

const inCountry = (x: number, y: number) => {
  let hit = false;
  for (const r of COUNTRY) {
    for (let i = 0, j = r.length - 1; i < r.length; j = i++) {
      const [xi, yi] = r[i];
      const [xj, yj] = r[j];
      if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) hit = !hit;
    }
  }
  return hit;
};

/**
 * Kota pesisir bisa jatuh SEDIKIT DI LUAR poligon setelah penyederhanaan RDP
 * (toleransi ~0,45 km) + pembulatan integer (±0,44 km). Penambal ini menarik
 * kota pesisir yang meleset ke titik terdekat DI DALAM poligon — otomatis,
 * jadi berlaku untuk negara mana pun yang dipasang nanti.
 */
const snapInside = (x: number, y: number): [number, number] => {
  if (inCountry(x, y)) return [x, y];
  let bx = x;
  let by = y;
  let best = 1e9;
  for (const r of COUNTRY) {
    for (let i = 0, j = r.length - 1; i < r.length; j = i++) {
      const [x1, y1] = r[j];
      const [x2, y2] = r[i];
      const dx = x2 - x1;
      const dy = y2 - y1;
      const L = dx * dx + dy * dy || 1;
      let u = ((x - x1) * dx + (y - y1) * dy) / L;
      u = Math.max(0, Math.min(1, u));
      const px = x1 + u * dx;
      const py = y1 + u * dy;
      const d = Math.hypot(x - px, y - py);
      if (d < best) {
        best = d;
        bx = px;
        by = py;
      }
    }
  }
  const dx = bx - x;
  const dy = by - y;
  const L = Math.hypot(dx, dy);
  if (L > 0.001) {
    for (let m = 1.5; m <= 30; m += 1.5) {
      const nx = bx + (dx / L) * m;
      const ny = by + (dy / L) * m;
      if (inCountry(nx, ny)) return [nx, ny];
    }
  }
  // Kota yang TEPAT di atas garis: arah dorong degenerasi, jadi
  // cari ke segala arah sampai menemukan sisi darat.
  for (let m = 1.5; m <= 30; m += 1.5) {
    for (let k = 0; k < 16; k++) {
      const a = (k / 16) * Math.PI * 2;
      const nx = bx + Math.cos(a) * m;
      const ny = by + Math.sin(a) * m;
      if (inCountry(nx, ny)) return [nx, ny];
    }
  }
  return [bx, by];
};
CITIES.forEach((c) => {
  const [nx, ny] = snapInside(c.x, c.y);
  c.x = nx;
  c.y = ny;
});

const ORIGIN = CITIES[0]; // Ottawa — ibu kota, pusat sapuan radar
const POPMAX = Math.max(...CITIES.map((c) => c.pop)); // skala tinggi kolom
const RMAX = 880; // jarak terjauh Ottawa ke tepi peta = 827 unit

/* ══════════════════════════════════════════ GEOMETRI TURUNAN */

type Dot = {x: number; y: number; d: number; sd: number; r: number};
type Ring = {pts: P2[]; cum: number[]; len: number};

// Hanya kota yang PUNYA LABEL yang dapat kolom cahaya — kolom tanpa nama
// terbaca sebagai batang nyasar.
const NCOL = 8;
const NLABEL = 8;

// Skala tinggi kolom. Kanada punya rentang paling ekstrem di seri ini:
// Toronto 5,21 jt lawan Yellowknife 20 rb — 260 kali lipat. Dengan pangkat
// 0,62 rasio tingginya jadi 276 px lawan 82 px, dan itu memang jujur:
// kolom kerdil di utara adalah faktanya, bukan kesalahan penskalaan. Justru
// kontras itu yang menceritakan sebaran penduduk Kanada.
const HBASE = 76;
const HSPAN = 200;
const HEXP = 0.62;

const buildGeo = () => {
  const dots: Dot[] = [];
  const STEP = 9.4; // ~3800 titik di dalam poligon Kanada
  // Batas iterasi diturunkan dari bbox, bukan konstanta 110: kalau STEP
  // lebih kecil dari bbox/110 peta akan terpotong diam-diam.
  const NY = Math.ceil((MB.y2 - MB.y1) / STEP) + 1;
  const NX = Math.ceil((MB.x2 - MB.x1) / STEP) + 1;
  for (let iy = 0; iy < NY; iy++) {
    const y = MB.y1 + iy * STEP;
    if (y > MB.y2) break;
    for (let ix = 0; ix < NX; ix++) {
      const x = MB.x1 + ix * STEP + (iy % 2) * STEP * 0.5;
      if (x > MB.x2) break;
      if (!inCountry(x, y)) continue;
      const k = dots.length;
      dots.push({
        x,
        y,
        d: Math.hypot(x - ORIGIN.x, y - ORIGIN.y),
        sd: random('dd' + k) * 120,
        r: 0.78 + random('dr' + k) * 0.62,
      });
    }
  }

  const mkRing = (pts: P2[]): Ring => {
    const cum = [0];
    let L = 0;
    for (let i = 1; i < pts.length; i++) {
      L += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
      cum.push(L);
    }
    return {pts, cum, len: L};
  };
  const cRings = COUNTRY.map(mkRing).sort((a, b) => b.len - a.len);

  const maxD = Math.max(...CITIES.map((c) => Math.hypot(c.x - ORIGIN.x, c.y - ORIGIN.y)));
  return {dots, cRings, maxD};
};

const easeIO = (u: number) =>
  u <= 0 ? 0 : u >= 1 ? 1 : u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
const cl01 = (u: number) => Math.max(0, Math.min(1, u));

/* ═════════════════════════════════════════════════════════ SCENE */

const Scene: React.FC<{t: number}> = ({t}) => {
  const out = useRef<HTMLCanvasElement | null>(null);
  const bloom = useRef<HTMLCanvasElement | null>(null);
  const geo = useMemo(buildGeo, []);

  /**
   * Offset label dihitung SEKALI pada pose kamera acuan (pertengahan klip),
   * lalu dipakai tetap sepanjang klip. Kalau dihitung per-frame, sisi label
   * bisa berbalik di tengah gerakan kamera dan terlihat meloncat.
   * Kandidat diurutkan dari yang PALING DEKAT ke puncak kolom, jadi tali
   * penunjuknya pendek; yang jauh hanya dipakai kalau semua bertabrakan.
   */
  const LABEL_OFF = useMemo(() => {
    const pitch = 1.16;
    const cpt = Math.cos(pitch);
    const spt = Math.sin(pitch);
    const dolly = DIST + 39;
    const prRef = (mx: number, my: number, hgt: number): [number, number] => {
      const [x, z] = mw(mx, my);
      const y2 = hgt * cpt - z * spt;
      const z2 = hgt * spt + z * cpt;
      const sc = FOCAL / (dolly - z2);
      return [CXS + x * sc, CYS - y2 * sc];
    };
    const CW = 12.9; // lebar rata-rata glyph mono 18px + jarak huruf 3px
    const items = [];
    for (let i = 0; i < NLABEL; i++) {
      const ct = CITIES[i];
      const hN = Math.pow(ct.pop / POPMAX, HEXP);
      items.push({
        i,
        p: prRef(ct.x, ct.y, HBASE + hN * HSPAN),
        w: ct.n.length * CW + 22,
      });
    }
    const cand = (w: number): [number, number][] => [
      [26, -12], [26, 24], [-w - 26, -12], [-w - 26, 24],
      [26, -40], [-w - 26, -40], [26, 52], [-w - 26, 52],
      [52, -12], [-w - 52, -12], [26, 80], [-w - 26, 80],
      [86, -12], [-w - 86, -12], [26, 118], [-w - 26, 118],
      [26, -78], [-w - 26, -78], [130, 40], [-w - 130, 40],
    ];
    // Blok judul dianggap sudah "terisi" supaya label kota (mis. Yellowknife di
    // utara) tidak pernah ditempatkan menabrak teks HUD.
    const boxes: {x1: number; y1: number; x2: number; y2: number}[] = [
      {x1: 52, y1: 44, x2: 600, y2: 210},
    ];
    const out: [number, number][] = [];
    for (const it of items) {
      // Kalau ADA kandidat bersih, ambil yang pertama (paling dekat ke kolom).
      // Kalau TIDAK ADA, ambil yang tumpang-tindihnya paling kecil — bukan
      // kandidat pertama, karena kandidat pertama justru yang menabrak.
      let chosen: [number, number] | null = null;
      let fallback: [number, number] = [26, -12];
      let fbCost = Infinity;
      for (const c of cand(it.w)) {
        const r = {
          x1: it.p[0] + c[0] - 12,
          y1: it.p[1] + c[1] - 22,
          x2: it.p[0] + c[0] + it.w,
          y2: it.p[1] + c[1] + 10,
        };
        let cost = 0;
        for (const q of boxes) {
          const ox = Math.min(r.x2, q.x2) - Math.max(r.x1, q.x1);
          const oy = Math.min(r.y2, q.y2) - Math.max(r.y1, q.y1);
          if (ox > 0 && oy > 0) cost += ox * oy;
        }
        for (const o of items) {
          if (o === it) continue;
          if (
            o.p[0] > r.x1 - 16 && o.p[0] < r.x2 + 16 &&
            o.p[1] > r.y1 - 16 && o.p[1] < r.y2 + 16
          ) cost += 9000;
        }
        // label yang keluar frame juga dihukum
        if (r.x1 < 40 || r.x2 > W - 40 || r.y1 < 30 || r.y2 > H - 40) cost += 24000;
        if (cost === 0) {
          chosen = c;
          break;
        }
        if (cost < fbCost) {
          fbCost = cost;
          fallback = c;
        }
      }
      if (!chosen) chosen = fallback;
      boxes.push({
        x1: it.p[0] + chosen[0] - 12,
        y1: it.p[1] + chosen[1] - 22,
        x2: it.p[0] + chosen[0] + it.w,
        y2: it.p[1] + chosen[1] + 10,
      });
      out[it.i] = chosen;
    }
    return out;
  }, []);

  const stars = useMemo(
    () =>
      Array.from({length: 210}, (_, i) => ({
        x: random('sx' + i) * W,
        y: random('sy' + i) * H,
        r: 0.5 + Math.pow(random('sr' + i), 3) * 5,
        a: 0.09 + random('sa' + i) * 0.4,
        sd: random('ss' + i) * 90,
      })),
    []
  );

  useLayoutEffect(() => {
    const oc = out.current;
    if (!oc) return;
    const c = oc.getContext('2d', {alpha: false})!;
    c.setTransform(1, 0, 0, 1, 0, 0);
    c.filter = 'none';
    c.globalAlpha = 1;
    c.globalCompositeOperation = 'source-over';
    c.lineCap = 'round';
    c.lineJoin = 'round';

    const ang = 2 * Math.PI * (t / DUR);
    const n01 = (k: number, fr: number) =>
      0.5 + 0.5 * noise3D('m41', Math.cos(ang) * fr, Math.sin(ang) * fr, k);

    /* ── fase: terbentuk → hidup → terurai ── */
    const build = easeIO((t - 0.35) / 4.3);
    const fall = easeIO((t - 19.3) / 3.3);
    const form = build * (1 - fall);
    const live = cl01((form - 0.9) / 0.1);

    const formR = form * RMAX * 1.06;
    const outlineP = cl01((form - 0.04) / 0.72);
    const statesA = cl01((form - 0.42) / 0.36);

    /* ── kamera: satu siklus penuh per loop → mulus dan loop-aman ── */
    const yaw = 0.13 * Math.sin(ang);
    const pitch = 1.245 - 0.17 * (0.5 - 0.5 * Math.cos(ang));
    const cyw = Math.cos(yaw);
    const syw = Math.sin(yaw);
    const cpt = Math.cos(pitch);
    const spt = Math.sin(pitch);
    const dolly = DIST + 78 * (0.5 - 0.5 * Math.cos(ang)) - 20 * Math.sin(ang);

    const pr = (x: number, hgt: number, z: number) => {
      const x1 = x * cyw + z * syw;
      const z1 = -x * syw + z * cyw;
      const y2 = hgt * cpt - z1 * spt;
      const z2 = hgt * spt + z1 * cpt;
      const zc = dolly - z2;
      const s = FOCAL / zc;
      return [CXS + x1 * s, CYS - y2 * s, s] as [number, number, number];
    };
    const prMap = (mx: number, my: number, hgt = 0) => {
      const [wx, wz] = mw(mx, my);
      return pr(wx, hgt, wz);
    };

    /* ── latar ── */
    const bg = c.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#050b12');
    bg.addColorStop(0.5, '#07101a');
    bg.addColorStop(1, '#03070c');
    c.fillStyle = bg;
    c.fillRect(0, 0, W, H);
    const rg = c.createRadialGradient(CXS, CYS - 80, 60, CXS, CYS - 80, 1150);
    rg.addColorStop(0, `rgba(63,169,212,${(0.04 + 0.06 * form).toFixed(3)})`);
    rg.addColorStop(0.45, `rgba(232,17,45,${(0.012 + 0.025 * form).toFixed(3)})`);
    rg.addColorStop(1, 'rgba(3,7,12,0)');
    c.fillStyle = rg;
    c.fillRect(0, 0, W, H);

    for (const s of stars) {
      const tw = n01(s.sd * 0.3, 6);
      c.globalAlpha = s.a * (0.35 + 0.65 * tw);
      const g2 = c.createRadialGradient(s.x, s.y, 0, s.x, s.y, s.r * 3);
      g2.addColorStop(0, '#cfe9ff');
      g2.addColorStop(1, 'rgba(120,190,255,0)');
      c.fillStyle = g2;
      c.beginPath();
      c.arc(s.x, s.y, s.r * 3, 0, 6.2832);
      c.fill();
    }
    c.globalAlpha = 1;

    c.globalCompositeOperation = 'lighter';

    /* ── grid lantai ── */
    const GR = 1500;
    c.lineWidth = 1;
    c.strokeStyle = TEAL_DIM;
    for (let i = -8; i <= 8; i++) {
      const u = i / 8;
      c.globalAlpha = 0.22 * (1 - Math.abs(u));
      c.beginPath();
      let a = pr(u * GR, 0, -GR);
      let b = pr(u * GR, 0, GR);
      c.moveTo(a[0], a[1]);
      c.lineTo(b[0], b[1]);
      a = pr(-GR, 0, u * GR);
      b = pr(GR, 0, u * GR);
      c.moveTo(a[0], a[1]);
      c.lineTo(b[0], b[1]);
      c.stroke();
    }
    c.globalAlpha = 1;

    const radU = ((t / DUR) * 3) % 1;
    const radR = radU * RMAX;

    /* ── matriks titik ── */
    for (const d of geo.dots) {
      const app = cl01((formR - d.d) / 118);
      if (app <= 0.005) continue;
      const band = live * Math.exp(-Math.pow((d.d - radR) / 66, 2));
      const pop = Math.exp(-Math.pow((formR - d.d) / 90, 2)) * (1 - live);
      const tw = n01(d.sd * 0.22, 7);
      const p = prMap(d.x, d.y, (band + pop) * 30);
      const a = app * (0.24 + 0.3 * tw + band * 0.7 + pop * 0.8);
      const mix = Math.min(1, band * 1.3 + pop);
      const rr = d.r * (1 + (band + pop) * 1.2) * p[2];
      c.globalAlpha = Math.min(1, a);
      // Batu tulis saat diam → SIAN ES saat kena sapuan radar / gelombang
      // bentuk. Di sini peralihannya murni kontras TERANG dalam satu keluarga
      // dingin, bukan pertukaran corak seperti versi Arab Saudi — itu yang
      // membuat sapuannya terbaca seperti es yang tiba-tiba tersinari.
      c.fillStyle = `rgb(${Math.round(120 + 30 * mix)},${Math.round(152 + 88 * mix)},${Math.round(
        182 + 73 * mix
      )})`;
      c.beginPath();
      c.arc(p[0], p[1], rr, 0, 6.2832);
      c.fill();
    }
    c.globalAlpha = 1;

    /* ── cincin radar ── */
    if (live > 0.05 && radR > 30) {
      c.beginPath();
      for (let i = 0; i <= 90; i++) {
        const a2 = (i / 90) * Math.PI * 2;
        const p = prMap(ORIGIN.x + Math.cos(a2) * radR, ORIGIN.y + Math.sin(a2) * radR);
        i === 0 ? c.moveTo(p[0], p[1]) : c.lineTo(p[0], p[1]);
      }
      const fade = Math.pow(1 - radU, 0.9) * live;
      c.strokeStyle = AMBER;
      c.lineWidth = 8;
      c.globalAlpha = 0.04 * fade;
      c.stroke();
      c.lineWidth = 1.5;
      c.globalAlpha = 0.17 * fade;
      c.stroke();
      c.globalAlpha = 1;
    }

    /* ── batas negara bagian ── */
    if (statesA > 0.01) {
      c.strokeStyle = TEAL;
      c.lineWidth = 1;
      c.globalAlpha = 0.26 * statesA;
      c.beginPath();
      for (const r of STATES) {
        for (let i = 0; i < r.length; i++) {
          const p = prMap(r[i][0], r[i][1]);
          i === 0 ? c.moveTo(p[0], p[1]) : c.lineTo(p[0], p[1]);
        }
        c.closePath();
      }
      c.stroke();
      c.globalAlpha = 1;
    }

    /* ── garis negara: DIGAMBAR PROGRESIF sepanjang keliling ── */
    const buildCountryPath = () => {
      c.beginPath();
      for (let ri = 0; ri < geo.cRings.length; ri++) {
        const ring = geo.cRings[ri];
        const lead = ri === 0 ? 0 : Math.min(0.7, 0.3 + ri * 0.035);
        const rp = cl01((outlineP - lead) / (1 - lead));
        if (rp <= 0.001) continue;
        const target = ring.len * rp;
        const P = ring.pts;
        let started = false;
        for (let i = 0; i < P.length; i++) {
          if (ring.cum[i] > target && i > 0) {
            const prev = P[i - 1];
            const seg = ring.cum[i] - ring.cum[i - 1];
            const u = seg > 0 ? (target - ring.cum[i - 1]) / seg : 0;
            const q = prMap(
              prev[0] + (P[i][0] - prev[0]) * u,
              prev[1] + (P[i][1] - prev[1]) * u
            );
            c.lineTo(q[0], q[1]);
            break;
          }
          const p = prMap(P[i][0], P[i][1]);
          if (!started) {
            c.moveTo(p[0], p[1]);
            started = true;
          } else c.lineTo(p[0], p[1]);
          if (i === P.length - 1 && rp > 0.999) c.closePath();
        }
      }
    };
    // siluet "hantu" selalu ada tipis: frame seam tetap layak jadi poster
    c.beginPath();
    for (const r of COUNTRY) {
      for (let i = 0; i < r.length; i++) {
        const p = prMap(r[i][0], r[i][1]);
        i === 0 ? c.moveTo(p[0], p[1]) : c.lineTo(p[0], p[1]);
      }
      c.closePath();
    }
    c.strokeStyle = GOLD;
    c.lineWidth = 1.4;
    c.globalAlpha = 0.1 - 0.05 * form;
    c.stroke();
    c.globalAlpha = 1;

    const brea = 0.5 + 0.5 * Math.sin(ang * 3);
    if (outlineP > 0.001) {
      buildCountryPath();
      c.strokeStyle = GOLD;
      c.lineWidth = 20;
      c.globalAlpha = 0.05 + 0.025 * brea;
      c.stroke();
      c.lineWidth = 7;
      c.globalAlpha = 0.14 + 0.06 * brea;
      c.stroke();
      c.lineWidth = 2.4;
      c.strokeStyle = GOLD_HI;
      c.globalAlpha = 0.92;
      c.stroke();
      c.globalAlpha = 1;
    }

    /* ── kota ── */
    const tops: {i: number; top: [number, number, number]}[] = [];
    for (let i = 0; i < CITIES.length; i++) {
      const ct = CITIES[i];
      const dd = Math.hypot(ct.x - ORIGIN.x, ct.y - ORIGIN.y);
      const cp = cl01((form - 0.12 - (dd / geo.maxD) * 0.5) / 0.24);
      if (cp <= 0.01) continue;
      const hit = live * Math.max(0, 1 - Math.abs(dd - radR) / 150);
      const base = prMap(ct.x, ct.y);

      if (i < NCOL) {
        // Tinggi kolom TETAP. Versi sebelumnya memakai noise ber-frekuensi
        // ~5 Hz sehingga batang dan labelnya terbaca bergetar.
        const hNorm = Math.pow(ct.pop / POPMAX, HEXP);
        const hgt = (HBASE + hNorm * HSPAN) * cp;
        const top = prMap(ct.x, ct.y, hgt);
        tops.push({i, top});

        const lg = c.createLinearGradient(base[0], base[1], top[0], top[1]);
        lg.addColorStop(0, 'rgba(255,255,255,1)');
        lg.addColorStop(0.18, 'rgba(160,238,255,0.95)');
        lg.addColorStop(0.55, 'rgba(56,170,215,0.45)');
        lg.addColorStop(1, 'rgba(8,50,80,0)');
        c.strokeStyle = lg;
        c.lineWidth = (3 + hNorm * 4.2) * base[2];
        c.globalAlpha = 0.92 * cp;
        c.beginPath();
        c.moveTo(base[0], base[1]);
        c.lineTo(top[0], top[1]);
        c.stroke();
        c.lineWidth = (10 + hNorm * 14) * base[2];
        c.globalAlpha = 0.1 * cp;
        c.stroke();

        const g3 = c.createRadialGradient(top[0], top[1], 0, top[0], top[1], 15 * base[2]);
        g3.addColorStop(0, '#ffffff');
        g3.addColorStop(0.28, '#a0eeff');
        g3.addColorStop(0.62, 'rgba(56,170,215,0.5)');
        g3.addColorStop(1, 'rgba(8,50,80,0)');
        c.globalAlpha = (0.9 + 0.1 * hit) * cp;
        c.fillStyle = g3;
        c.beginPath();
        c.arc(top[0], top[1], 15 * base[2], 0, 6.2832);
        c.fill();

        const ph = ((t / DUR) * 6 + i * 0.17) % 1;
        const rr0 = (30 + hNorm * 34) * (0.4 + ph * 1.4);
        c.beginPath();
        for (let s = 0; s <= 36; s++) {
          const a2 = (s / 36) * Math.PI * 2;
          const p = prMap(ct.x + Math.cos(a2) * rr0, ct.y + Math.sin(a2) * rr0);
          s === 0 ? c.moveTo(p[0], p[1]) : c.lineTo(p[0], p[1]);
        }
        c.strokeStyle = SAFFRON;
        c.lineWidth = 1.5;
        c.globalAlpha = (1 - ph) * 0.34 * cp;
        c.stroke();
      } else {
        const tw = n01(i * 7 + 40, 4);
        c.globalAlpha = cp * (0.4 + 0.5 * tw);
        c.fillStyle = GOLD;
        c.beginPath();
        c.arc(base[0], base[1], 2.4 * base[2], 0, 6.2832);
        c.fill();
      }

      c.globalAlpha = cp;
      c.fillStyle = GOLD_HI;
      c.beginPath();
      c.arc(base[0], base[1], 2.2 * base[2], 0, 6.2832);
      c.fill();
    }
    c.globalAlpha = 1;
    c.globalCompositeOperation = 'source-over';

    /* ── label: 5 kota, nama saja ── */
    c.textBaseline = 'alphabetic';
    const labelA = cl01((form - 0.87) / 0.13);
    if (labelA > 0.01) {
      c.font = `400 18px ${MONO}`;
      for (const tp of tops) {
        if (tp.i >= NLABEL) continue;
        const off = LABEL_OFF[tp.i] || [26, -12];
        const lx = tp.top[0] + off[0];
        const ly = tp.top[1] + off[1];
        c.globalAlpha = labelA * 0.5;
        c.strokeStyle = GOLD;
        c.lineWidth = 1;
        c.beginPath();
        c.moveTo(tp.top[0] + (off[0] > 0 ? 6 : -6), tp.top[1] + 1);
        c.lineTo(off[0] > 0 ? lx - 7 : lx + CITIES[tp.i].n.length * 12.9 + 9, ly - 5);
        c.stroke();
        // Peta seluas Kanada membuat label jatuh DI DALAM daratan,
        // jadi setiap label perlu alas gelap supaya tetap terbaca.
        (c as any).letterSpacing = '3px';
        const label = CITIES[tp.i].n.toUpperCase();
        const wdt = c.measureText(label).width;
        c.globalAlpha = labelA * 0.72;
        c.fillStyle = 'rgba(3,10,20,1)';
        c.fillRect(lx - 9, ly - 19, wdt + 20, 27);
        c.globalAlpha = labelA * 0.75;
        c.fillStyle = GOLD;
        c.fillRect(lx - 9, ly - 19, 2.5, 27);
        c.globalAlpha = labelA;
        c.fillStyle = LABEL_TXT;
        c.fillText(label, lx, ly);
        (c as any).letterSpacing = '0px';
      }
    }
    c.globalAlpha = 1;

    /* ── vignette ── */
    const vg = c.createRadialGradient(CXS, CYS, 400, CXS, CYS, 1250);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, 'rgba(0,0,0,0.8)');
    c.fillStyle = vg;
    c.fillRect(0, 0, W, H);

    const bc = bloom.current;
    if (bc) {
      const bx = bc.getContext('2d', {alpha: false})!;
      bx.fillStyle = '#000';
      bx.fillRect(0, 0, 480, 270);
      bx.drawImage(oc, 0, 0, 480, 270);
    }
  });

  return (
    <>
      <canvas
        ref={out}
        width={W}
        height={H}
        style={{position: 'absolute', inset: 0, width: '100%', height: '100%'}}
      />
      <canvas
        ref={bloom}
        width={480}
        height={270}
        style={{
          position: 'absolute',
          inset: 0,
          width: '100%',
          height: '100%',
          filter: 'blur(12px)',
          mixBlendMode: 'screen',
          opacity: 0.44,
        }}
      />
    </>
  );
};

/* ══════════════════════════════════ HUD (sengaja sangat minim) */

const Hud: React.FC<{t: number}> = ({t}) => {
  const op = easeIO((t - 1.6) / 1.4) * (1 - easeIO((t - 20.2) / 1.6));
  return (
    <g opacity={op}>
      <g transform="translate(104,142)">
        {/* "CANADA" cuma 6 karakter, jadi kembali ke ukuran penuh seri ini
            (72px/17sp = 370 px) tanpa risiko menabrak peta. */}
        <rect x={-22} y={-58} width={5} height={82} fill={SAFFRON} opacity={0.95} />
        <text fontFamily={TITLE} fontSize={72} fill={LABEL_TXT} letterSpacing={17}>
          CANADA
        </text>
        <text y={34} fontFamily={MONO} fontSize={17} fill={AMBER} letterSpacing={7.4}>
        </text>
      </g>
      <g stroke={GOLD} strokeWidth={2.2} fill="none" opacity={0.4}>
        <path d="M116,58 L58,58 L58,116" />
        <path d={`M${W - 116},58 L${W - 58},58 L${W - 58},116`} />
        <path d={`M116,${H - 58} L58,${H - 58} L58,${H - 116}`} />
        <path d={`M${W - 116},${H - 58} L${W - 58},${H - 58} L${W - 58},${H - 116}`} />
      </g>
    </g>
  );
};

/* ══════════════════════════════════════════════════════════ MAIN */

export const Motion: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  useEmbeddedFonts();

  const F = ((frame % DUR_F) + DUR_F) % DUR_F;
  const t = F / fps;

  return (
    <AbsoluteFill style={{background: '#02060f', overflow: 'hidden'}}>
      <Scene t={t} />
      <svg width={W} height={H} viewBox={`0 0 ${W} ${H}`} style={{position: 'absolute', inset: 0}}>
        <Hud t={t} />
      </svg>
    </AbsoluteFill>
  );
};

export default Motion;
